def upstream_overlapping_AID_WRC_motif(X):
    seq = X["raw_sequence"].astype(str).str.upper()
    return (
        seq.str.len().ge(5)
        & seq.str[2].isin(["A", "T"])
        & seq.str[3].isin(["A", "G"])
        & seq.str[4].eq("A")
    ).astype(int).rename("upstream_overlapping_AID_WRC_motif")
